head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vPRELM_INVSTG_BZ_PROCS_NO;
scwin.vListProcsStatCd;
scwin.TR_JOB;
scwin.mktTpCd; //거래시장구분 1= 유가, 2=코스닥
//var gAfStdIndCd = "";

scwin.vScrenID = "ULDSTF05106.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read_sync = function() {
    //alert("LST_LM_CD :"+LST_LM_CD);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectKindStkDtl&inputMessageId=KIND_STK_PREEXAM_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    if (dts_Item.getCellData(1, "BZ_PROCS_NO") == '') {
        buttonSet.setInsertStatus();
        url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectKindStkDtl&inputMessageId=KIND_STK_PREEXAM_SEARCH_OUT";
        url += "&BZ_PROCS_NO=" + scwin.vPRELM_INVSTG_BZ_PROCS_NO;
        dts_Item.DataID = encodeURI(url);
        dts_Item.Reset();
        if (dts_Item.getCellData(1, "BZ_PROCS_NO") != '') {
            dts_Item.setCellData('1', "BZ_PROCS_NO", '');
        } else {
            dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIND_STK_DTL_INOUT";
            dts_Item.reset();
            dts_Item.insertRow();
        }
    } else {
        buttonSet.setUpdateStatus();
    }
};
scwin.initForm = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    if (dts_Item.getCellData(1, "ACCTP_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "ACCTP_YN") == '') dts_Item.NameValue(1, "ACCTP_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CASH_DIV_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "CASH_DIV_YN") == '') dts_Item.NameValue(1, "CASH_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CMSTK_PCT1_DIV_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "CMSTK_PCT1_DIV_YN") == '') dts_Item.NameValue(1, "CMSTK_PCT1_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_CASH_REDMPT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_CASH_REDMPT_YN") == '') dts_Item.NameValue(1, "COM_CASH_REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_CONV_RGHT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_CONV_RGHT_YN") == '') dts_Item.NameValue(1, "COM_CONV_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_REDMPT_RGHT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_REDMPT_RGHT_YN") == '') dts_Item.NameValue(1, "COM_REDMPT_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CONV_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "CONV_YN") == '') dts_Item.NameValue(1, "CONV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "LWST_DIV_RT_DSC_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "LWST_DIV_RT_DSC_YN") == '') dts_Item.NameValue(1, "LWST_DIV_RT_DSC_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "MISC_DIV_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "MISC_DIV_YN") == '') dts_Item.NameValue(1, "MISC_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "NDIVTM_VOTERGHT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "NDIVTM_VOTERGHT_YN") == '') dts_Item.NameValue(1, "NDIVTM_VOTERGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PARTCTP_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "PARTCTP_YN") == '') dts_Item.NameValue(1, "PARTCTP_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_REMK") == '') /*ORG SRC: if (dts_Item.NameValue(1, "PROFT_DIV_REMK") == '') dts_Item.NameValue(1, "PROFT_DIV_REMK") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "PROFT_DIV_YN") == '') dts_Item.NameValue(1, "PROFT_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "REDMPT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "REDMPT_YN") == '') dts_Item.NameValue(1, "REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "REMAIN_PROPRT_DISTR_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "REMAIN_PROPRT_DISTR_YN") == '') dts_Item.NameValue(1, "REMAIN_PROPRT_DISTR_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_CASH_REDMPT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_CASH_REDMPT_YN") == '') dts_Item.NameValue(1, "SHRHD_CASH_REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_CONV_RGHT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_CONV_RGHT_YN") == '') dts_Item.NameValue(1, "SHRHD_CONV_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_REDMPT_RGHT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_REDMPT_RGHT_YN") == '') dts_Item.NameValue(1, "SHRHD_REDMPT_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "VOTERGHT_EXCLD_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "VOTERGHT_EXCLD_YN") == '') dts_Item.NameValue(1, "VOTERGHT_EXCLD_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "VOTERGHT_LMT_YN") == '') /*ORG SRC: if (dts_Item.NameValue(1, "VOTERGHT_LMT_YN") == '') dts_Item.NameValue(1, "VOTERGHT_LMT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_YN") == "1") {
        $c.stf.showObj(panel_1, true);
    } else {
        $c.stf.showObj(panel_1, false);
    }
    if (dts_Item.getCellData(1, "REMAIN_PROPRT_DISTR_YN") == 1) {
        $c.stf.showObj(panel_2, true);
    } else {
        $c.stf.showObj(panel_2, false);
    }
    if (dts_Item.getCellData(1, "VOTERGHT_EXCLD_YN") == 1) {
        $c.stf.showObj(panel_3, true);
    } else {
        $c.stf.showObj(panel_3, false);
    }
    if (dts_Item.getCellData(1, "VOTERGHT_LMT_YN") == 1) {
        $c.stf.showObj(panel_4, true);
    } else {
        $c.stf.showObj(panel_4, false);
    }
    if (dts_Item.getCellData(1, "REDMPT_YN") == 1) {
        if (dts_Item.getCellData(1, "COM_REDMPT_RGHT_YN") == 1) {
            $c.stf.showObj(panel_6, true);
        } else {
            $c.stf.showObj(panel_6, false);
        }
        if (dts_Item.getCellData(1, "SHRHD_REDMPT_RGHT_YN") == 1) {
            $c.stf.showObj(panel_7, true);
        } else {
            $c.stf.showObj(panel_7, false);
        }
        $c.stf.showObj(panel_5, true);
    } else {
        $c.stf.showObj(panel_6, false);
        $c.stf.showObj(panel_7, false);
        $c.stf.showObj(panel_5, false);
    }
    if (dts_Item.getCellData(1, "CONV_YN") == 1) {
        if (dts_Item.getCellData(1, "COM_CONV_RGHT_YN") == 1) {
            $c.stf.showObj(panel_9, true);
        } else {
            $c.stf.showObj(panel_9, false);
        }
        if (dts_Item.getCellData(1, "SHRHD_CONV_RGHT_YN") == 1) {
            $c.stf.showObj(panel_10, true);
        } else {
            $c.stf.showObj(panel_10, false);
        }
        $c.stf.showObj(panel_8, true);
    } else {
        $c.stf.showObj(panel_9, false);
        $c.stf.showObj(panel_10, false);
        $c.stf.showObj(panel_8, false);
    }
};
scwin.fn_checkForm = function() {
    //todo
    var PROFT_DIV_YN = $c.stf.getObjectValue(chk_PROFT_DIV_YN); /* 이익배당여부         */
    //var CMSTK_PCT1_DIV_YN         = getObjectValue(chk_CMSTK_PCT1_DIV_YN          ); /* 보통주1%배당여부     */ 
    //var LWST_DIV_RT_DSC_YN        = getObjectValue(chk_LWST_DIV_RT_DSC_YN         ); /* 최저배당율기재여부   */ 
    //var MISC_DIV_YN               = getObjectValue(chk_MISC_DIV_YN                ); /* 기타배당여부         */ 
    //var CASH_DIV_YN               = getObjectValue(chk_CASH_DIV_YN                ); /* 현금배당여부         */ 
    //var PARTCTP_YN                = getObjectValue(chk_PARTCTP_YN                 ); /* 참가형여부           */ 
    //var DIV_RT                    = getObjectValue(tbx_DIV_RT                     ); /* 배당률               */ 
    //var ACCTP_YN                  = getObjectValue(chk_ACCTP_YN                   ); /* 누적형여부           */ 
    //var NDIVTM_VOTERGHT_YN        = getObjectValue(chk_NDIVTM_VOTERGHT_YN         ); /* 무배당시의결권여부   */ 
    //var PROFT_DIV_REMK            = getObjectValue(tbx_PROFT_DIV_REMK             ); /* 이익배당비고         */ 
    var REMAIN_PROPRT_DISTR_YN = $c.stf.getObjectValue(chk_REMAIN_PROPRT_DISTR_YN); /* 잔여재산분배여부     */
    //var REMAIN_PROPRT_DISTR_REMK  = getObjectValue(tbx_REMAIN_PROPRT_DISTR_REMK   ); /* 잔여재산분배비고     */ 
    var VOTERGHT_EXCLD_YN = $c.stf.getObjectValue(chk_VOTERGHT_EXCLD_YN); /* 의결권배제여부       */
    //var VOTERGHT_EXCLD_REMK       = getObjectValue(tbx_VOTERGHT_EXCLD_REMK        ); /* 의결권배제비고       */ 
    var VOTERGHT_LMT_YN = $c.stf.getObjectValue(chk_VOTERGHT_LMT_YN); /* 의결권제한여부       */
    //var VOTERGHT_LMT_CONTN        = getObjectValue(tbx_VOTERGHT_LMT_CONTN         ); /* 의결권제한사항       */ 
    //var VOTERGHT_LMT_REMK         = getObjectValue(tbx_VOTERGHT_LMT_REMK          ); /* 의결권제한비고       */ 
    var REDMPT_YN = $c.stf.getObjectValue(chk_REDMPT_YN); /* 상환여부             */
    //var COM_REDMPT_RGHT_YN        = getObjectValue(chk_COM_REDMPT_RGHT_YN         ); /* 회사상환권리여부     */ 
    //var COM_REDMPT_PD_END_DD      = getObjectValue(tbx_COM_REDMPT_PD_END_DD       ); /* 회사상환기간종료일자 */ 
    //var COM_REDMPT_PD_STRT_DD     = getObjectValue(tbx_COM_REDMPT_PD_STRT_DD      ); /* 회사상환기간시작일자 */ 
    //var COM_CASH_REDMPT_YN        = getObjectValue(chk_COM_CASH_REDMPT_YN         ); /* 회사현금상환여부     */ 
    //var COM_REDMPT_REMK           = getObjectValue(tbx_COM_REDMPT_REMK            ); /* 회사상환비고         */ 
    //var SHRHD_REDMPT_RGHT_YN      = getObjectValue(chk_SHRHD_REDMPT_RGHT_YN       ); /* 주주상환권리여부     */ 
    //var SHRHD_REDMPT_PD_END_DD    = getObjectValue(tbx_SHRHD_REDMPT_PD_END_DD     ); /* 주주상환기간종료일자 */ 
    //var SHRHD_REDMPT_PD_STRT_DD   = getObjectValue(tbx_SHRHD_REDMPT_PD_STRT_DD    ); /* 주주상환기간시작일자 */ 
    //var SHRHD_CASH_REDMPT_YN      = getObjectValue(chk_SHRHD_CASH_REDMPT_YN       ); /* 주주현금상환여부     */ 
    //var SHRHD_REDMPT_REMK         = getObjectValue(tbx_SHRHD_REDMPT_REMK          ); /* 주주상환비고         */ 
    var CONV_YN = $c.stf.getObjectValue(chk_CONV_YN); /* 전환여부             */
    //var COM_CONV_RGHT_YN          = getObjectValue(chk_COM_CONV_RGHT_YN           ); /* 회사전환권리여부     */ 
    //var COM_CONV_RTO              = getObjectValue(tbx_COM_CONV_RTO               ); /* 회사전환비율         */ 
    //var COM_CONV_OBJ_STK_CONTN    = getObjectValue(tbx_SHRHD_CONV_OBJ_STK_CONTN   ); /* 회사전환대상주식내용 */ 
    //var COM_CONV_PD_STRT_DD       = getObjectValue(tbx_COM_CONV_PD_STRT_DD        ); /* 회사전환기간시작일자 */ 
    //var COM_CONV_PD_END_DD        = getObjectValue(tbx_COM_CONV_PD_END_DD       ); /* 회사전환기간종료일자 */ 
    //var COM_CONV_REMK             = getObjectValue(tbx_COM_CONV_REMK              ); /* 회사전환비고         */ 
    //var SHRHD_CONV_RGHT_YN        = getObjectValue(chk_SHRHD_CONV_RGHT_YN         ); /* 주주전환권리여부     */ 
    //var SHRHD_CONV_RTO            = getObjectValue(tbx_SHRHD_CONV_RTO             ); /* 주주전환비율         */ 
    //var SHRHD_CONV_OBJ_STK_CONTN  = getObjectValue(tbx_SHRHD_CONV_OBJ_STK_CONTN   ); /* 주주전환대상주식내용 */ 
    //var SHRHD_CONV_PD_STRT_DD     = getObjectValue(tbx_SHRHD_CONV_PD_STRT_DD      ); /* 주주전환기간시작일자 */ 
    //var SHRHD_CONV_PD_END_DD      = getObjectValue(tbx_SHRHD_CONV_PD_END_DD       ); /* 주주전환기간종료일자 */ 
    //var SHRHD_CONV_REMK           = getObjectValue(tbx_SHRHD_CONV_REMK            ); /* 주주전환비고         */ 


    if (PROFT_DIV_YN == 'N' && REMAIN_PROPRT_DISTR_YN == 'N' && VOTERGHT_EXCLD_YN == 'N' && VOTERGHT_LMT_YN == 'N' && REDMPT_YN == 'N' && CONV_YN == 'N') {
        $c.win.alert("입력된 종류주식 상세내역이 없습니다.\n입력 데이터를 확인해 주십시오.");
        return false;
    }
    if (dts_Item.getCellData(1, "REDMPT_YN") == 0) {
        if (window.confirm("[상환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) {
            dts_Item.setCellData(1, "COM_REDMPT_RGHT_YN", 0);
            dts_Item.setCellData(1, "SHRHD_REDMPT_RGHT_YN", 0);
            dts_Item.setCellData(1, "COM_REDMPT_PD_STRT_DD", '');
            dts_Item.setCellData(1, "COM_CASH_REDMPT_YN", 0);
            dts_Item.setCellData(1, "COM_REDMPT_REMK", '');
            dts_Item.setCellData(1, "SHRHD_REDMPT_PD_STRT_DD", '');
            dts_Item.setCellData(1, "SHRHD_REDMPT_PD_END_DD", '');
            dts_Item.setCellData(1, "SHRHD_CASH_REDMPT_YN", 0);
            dts_Item.setCellData(1, "SHRHD_REDMPT_REMK", '');
        } else {
            return false;
        }
    }
    if (dts_Item.getCellData(1, "CONV_YN") == 0) {
        if (window.confirm("[전환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) {
            dts_Item.setCellData(1, "COM_CONV_RGHT_YN", 0);
            dts_Item.setCellData(1, "COM_CONV_RTO", 0);
            dts_Item.setCellData(1, "COM_CONV_OBJ_STK_CONTN", '');
            dts_Item.setCellData(1, "COM_CONV_PD_STRT_DD", '');
            dts_Item.setCellData(1, "COM_CONV_PD_END_DD", '');
            dts_Item.setCellData(1, "COM_CONV_REMK", '');
            dts_Item.setCellData(1, "SHRHD_CONV_RGHT_YN", 0);
            dts_Item.setCellData(1, "SHRHD_CONV_RTO", 0);
            dts_Item.setCellData(1, "SHRHD_CONV_OBJ_STK_CONTN", '');
            dts_Item.setCellData(1, "SHRHD_CONV_PD_STRT_DD", '');
            dts_Item.setCellData(1, "SHRHD_CONV_PD_END_DD", '');
            dts_Item.setCellData(1, "SHRHD_CONV_REMK", '');
        } else {
            return false;
        }
    }
    return true;
};
scwin.fn_save = function() {
    if (!scwin.fn_checkForm()) {
        return;
    }
    scwin.TR_JOB = 'I';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/
        X = TB_JOB_INSERT;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        //alert("BZ_PROCS_NO>>>>>>>> :"+dts_Item.NameValue(1,"BZ_PROCS_NO"));

        scwin.fn_trs();
    }
};
scwin.fn_update = function() {
    if (!scwin.fn_checkForm()) {
        return;

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    }
    scwin.TR_JOB = 'U';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    }
    //        dts_Item.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;

    trs_Save.Action = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKindStkDtl";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function() {

};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_read_sync();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    scwin.vListProcsStatCd = parentWin.scwin.vListProcsStatCd;
    scwin.vPRELM_INVSTG_BZ_PROCS_NO = parentWin.scwin.vPRELM_INVSTG_BZ_PROCS_NO;
    scwin.mktTpCd = parentWin.scwin.mktTpCd;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정

    //alert("vBzProcsNo :"+vBzProcsNo);
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
    } else {
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIND_STK_DTL_INOUT";
        dts_Item.reset();
        dts_Item.insertRow();
    }
    scwin.initForm();
};
